<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Debate Engine</title>
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #0f1117;
      --surface: #1a1d27;
      --border: #2a2d3a;
      --accent: #5b7fff;
      --accent-hover: #7a96ff;
      --against: #ff5b5b;
      --against-hover: #ff7a7a;
      --for: #3dd68c;
      --text: #e2e4ee;
      --muted: #8b8fa8;
      --error-bg: #3a1a1a;
      --error-border: #8b2222;
      --radius: 8px;
      --font: 'Segoe UI', system-ui, -apple-system, sans-serif;
    }

    body {
      background: var(--bg);
      color: var(--text);
      font-family: var(--font);
      font-size: 15px;
      line-height: 1.6;
      min-height: 100vh;
    }

    /* ── Header ── */
    header {
      background: var(--surface);
      border-bottom: 1px solid var(--border);
      padding: 14px 24px;
      display: flex;
      align-items: center;
      gap: 16px;
      flex-wrap: wrap;
    }

    header h1 {
      font-size: 1.2rem;
      font-weight: 700;
      letter-spacing: 0.02em;
      color: var(--text);
      white-space: nowrap;
    }

    header h1 span { color: var(--accent); }

    #base-url-wrap {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-left: auto;
    }

    #base-url-wrap label {
      color: var(--muted);
      font-size: 0.85rem;
      white-space: nowrap;
    }

    #base-url-input {
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      color: var(--text);
      font-family: monospace;
      font-size: 0.85rem;
      padding: 5px 10px;
      width: 220px;
    }

    #base-url-input:focus { outline: none; border-color: var(--accent); }

    /* ── Nav ── */
    nav {
      background: var(--surface);
      border-bottom: 1px solid var(--border);
      padding: 0 24px;
      display: flex;
      gap: 4px;
    }

    .nav-btn {
      background: none;
      border: none;
      border-bottom: 2px solid transparent;
      color: var(--muted);
      cursor: pointer;
      font-family: var(--font);
      font-size: 0.9rem;
      padding: 10px 14px;
      transition: color 0.15s, border-color 0.15s;
    }

    .nav-btn:hover { color: var(--text); }
    .nav-btn.active { color: var(--accent); border-bottom-color: var(--accent); }

    /* ── Error banner ── */
    #error-banner {
      display: none;
      background: var(--error-bg);
      border: 1px solid var(--error-border);
      border-radius: var(--radius);
      color: #ff8080;
      font-size: 0.9rem;
      margin: 16px 24px 0;
      padding: 10px 14px;
      position: relative;
    }

    #error-banner button {
      background: none;
      border: none;
      color: #ff8080;
      cursor: pointer;
      font-size: 1.1rem;
      line-height: 1;
      position: absolute;
      right: 10px;
      top: 8px;
    }

    /* ── Main ── */
    main {
      max-width: 900px;
      margin: 0 auto;
      padding: 24px;
    }

    /* ── Views ── */
    .view { display: none; }
    .view.active { display: block; }

    /* ── Section heading ── */
    .section-head {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-bottom: 20px;
    }

    .section-head h2 {
      font-size: 1.15rem;
      font-weight: 600;
    }

    .section-head .count {
      background: var(--border);
      border-radius: 999px;
      color: var(--muted);
      font-size: 0.78rem;
      padding: 1px 8px;
    }

    /* ── Card list ── */
    .card-list {
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 16px 18px;
      cursor: pointer;
      transition: border-color 0.15s, background 0.15s;
    }

    .card:hover {
      border-color: var(--accent);
      background: #1e2133;
    }

    .card h3 {
      font-size: 1rem;
      font-weight: 600;
      margin-bottom: 4px;
    }

    .card p {
      color: var(--muted);
      font-size: 0.88rem;
    }

    .card .meta {
      color: var(--muted);
      font-size: 0.78rem;
      margin-top: 8px;
    }

    /* ── Empty state ── */
    .empty {
      color: var(--muted);
      font-size: 0.9rem;
      padding: 32px 0;
      text-align: center;
    }

    /* ── Buttons ── */
    .btn {
      border: none;
      border-radius: var(--radius);
      cursor: pointer;
      font-family: var(--font);
      font-size: 0.9rem;
      font-weight: 600;
      padding: 8px 18px;
      transition: background 0.15s, opacity 0.15s;
    }

    .btn:disabled { opacity: 0.5; cursor: not-allowed; }

    .btn-primary {
      background: var(--accent);
      color: #fff;
    }

    .btn-primary:not(:disabled):hover { background: var(--accent-hover); }

    .btn-secondary {
      background: var(--border);
      color: var(--text);
    }

    .btn-secondary:not(:disabled):hover { background: #363a52; }

    .btn-sm { font-size: 0.82rem; padding: 5px 12px; }

    /* ── Back link ── */
    .back-link {
      background: none;
      border: none;
      color: var(--accent);
      cursor: pointer;
      font-family: var(--font);
      font-size: 0.88rem;
      margin-bottom: 16px;
      padding: 0;
    }

    .back-link:hover { text-decoration: underline; }

    /* ── Debate detail ── */
    .debate-header {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      margin-bottom: 20px;
      padding: 20px;
    }

    .debate-header h2 { font-size: 1.2rem; margin-bottom: 6px; }

    .debate-header p {
      color: var(--muted);
      font-size: 0.9rem;
      margin-bottom: 10px;
    }

    .debate-header .meta { color: var(--muted); font-size: 0.78rem; }

    /* ── Argument columns ── */
    .args-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
      margin-bottom: 24px;
    }

    @media (max-width: 600px) {
      .args-grid { grid-template-columns: 1fr; }
    }

    .args-col h3 {
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.06em;
      margin-bottom: 10px;
      text-transform: uppercase;
    }

    .args-col.for h3 { color: var(--for); }
    .args-col.against h3 { color: var(--against); }

    .arg-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      font-size: 0.88rem;
      margin-bottom: 8px;
      padding: 12px 14px;
    }

    .args-col.for .arg-card { border-left: 3px solid var(--for); }
    .args-col.against .arg-card { border-left: 3px solid var(--against); }

    .arg-card .arg-meta {
      color: var(--muted);
      font-size: 0.75rem;
      margin-top: 6px;
    }

    /* ── Post argument inline form ── */
    .post-arg-panel {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 18px;
    }

    .post-arg-panel h3 {
      font-size: 0.95rem;
      font-weight: 600;
      margin-bottom: 14px;
    }

    .side-toggle {
      display: flex;
      gap: 8px;
      margin-bottom: 12px;
    }

    .side-btn {
      border: 1px solid var(--border);
      border-radius: var(--radius);
      background: var(--bg);
      color: var(--muted);
      cursor: pointer;
      font-family: var(--font);
      font-size: 0.85rem;
      font-weight: 600;
      padding: 6px 16px;
      transition: all 0.15s;
    }

    .side-btn.active-for {
      background: rgba(61,214,140,0.12);
      border-color: var(--for);
      color: var(--for);
    }

    .side-btn.active-against {
      background: rgba(255,91,91,0.12);
      border-color: var(--against);
      color: var(--against);
    }

    /* ── Forms ── */
    .form-group {
      margin-bottom: 14px;
    }

    .form-group label {
      display: block;
      color: var(--muted);
      font-size: 0.83rem;
      font-weight: 600;
      letter-spacing: 0.04em;
      margin-bottom: 5px;
      text-transform: uppercase;
    }

    input[type="text"],
    textarea {
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      color: var(--text);
      font-family: var(--font);
      font-size: 0.92rem;
      padding: 9px 12px;
      width: 100%;
      resize: vertical;
    }

    input[type="text"]:focus,
    textarea:focus {
      outline: none;
      border-color: var(--accent);
    }

    textarea { min-height: 80px; }

    .form-actions {
      display: flex;
      gap: 8px;
      justify-content: flex-end;
      margin-top: 16px;
    }

    /* ── Loading spinner ── */
    .spinner {
      display: inline-block;
      width: 16px;
      height: 16px;
      border: 2px solid var(--border);
      border-top-color: var(--accent);
      border-radius: 50%;
      animation: spin 0.6s linear infinite;
      vertical-align: middle;
      margin-right: 6px;
    }

    @keyframes spin { to { transform: rotate(360deg); } }

    .loading-msg {
      color: var(--muted);
      font-size: 0.9rem;
      padding: 24px 0;
      text-align: center;
    }
  </style>
</head>
