+  const container = document.getElementById('debate-list');
+  container.innerHTML = '<div class="loading-msg"><span class="spinner"></span>Loading…</div>';
+  document.getElementById('list-count').textContent = '…';
+  try {
+    const data = await apiFetch('/debates');
+    const debates = data.debates || [];
+    document.getElementById('list-count').textContent = debates.length;
+    if (debates.length === 0) {
+      container.innerHTML = '<div class="empty">No debates yet. Create the first one!</div>';
+      return;
+    }
+    container.innerHTML = '';
+    debates.forEach(d => {
+      const card = document.createElement('div');
+      card.className = 'card';
+      card.innerHTML = `
+        <h3>${escHtml(d.topic)}</h3>
+        ${d.description ? `<p>${escHtml(d.description)}</p>` : ''}
+        <div class="meta">${formatDate(d.created_at)}</div>
+      `;
+      card.addEventListener('click', () => showView('detail', d.id));
+      container.appendChild(card);
+    });
+  } catch (err) {
+    container.innerHTML = '';
+    showError('Failed to load debates: ' + err.message);
+  }
+}
+
+// ── Create debate ──────────────────────────────────────────────────
+
+async function submitCreateDebate(e) {
+  e.preventDefault();
+  const topic = document.getElementById('debate-topic').value.trim();
+  const description = document.getElementById('debate-desc').value.trim();
+  const btn = document.getElementById('create-submit-btn');
+  btn.disabled = true;
+  btn.textContent = 'Creating…';
+  try {
+    const debate = await apiFetch('/debates', {
+      method: 'POST',
+      body: JSON.stringify({ topic, description }),
+    });
+    showView('detail', debate.id);
+  } catch (err) {
+    showError('Failed to create debate: ' + err.message);
+  } finally {
+    btn.disabled = false;
+    btn.textContent = 'Create Debate';
+  }
+}
+
+// ── Debate detail ──────────────────────────────────────────────────
+
+async function loadDebateDetail(id) {
+  const container = document.getElementById('debate-detail-content');
+  container.innerHTML = '<div class="loading-msg"><span class="spinner"></span>Loading…</div>';
+  try {
+    const debate = await apiFetch(`/debates/${encodeURIComponent(id)}`);
+    renderDebateDetail(debate);
+  } catch (err) {
+    container.innerHTML = '';
+    showError('Failed to load debate: ' + err.message);
+  }
+}
+
+function renderDebateDetail(debate) {
+  const container = document.getElementById('debate-detail-content');
+  const args = debate.arguments || [];
+  const forArgs = args.filter(a => a.side === 'for');
+  const againstArgs = args.filter(a => a.side === 'against');
+
+  container.innerHTML = `
+    <div class="debate-header">
+      <h2>${escHtml(debate.topic)}</h2>
+      ${debate.description ? `<p>${escHtml(debate.description)}</p>` : ''}
+      <div class="meta">${formatDate(debate.created_at)}</div>
+    </div>
+
+    <div class="args-grid">
+      <div class="args-col for">
+        <h3>For (${forArgs.length})</h3>
+        ${forArgs.length === 0
+          ? '<div class="empty" style="padding:16px 0">No arguments yet.</div>'
+          : forArgs.map(a => `
+            <div class="arg-card">
+              ${escHtml(a.content)}
+              <div class="arg-meta">${formatDate(a.created_at)}</div>
+            </div>`).join('')}
+      </div>
+      <div class="args-col against">
+        <h3>Against (${againstArgs.length})</h3>
+        ${againstArgs.length === 0
+          ? '<div class="empty" style="padding:16px 0">No arguments yet.</div>'
+          : againstArgs.map(a => `
+            <div class="arg-card">
+              ${escHtml(a.content)}
+              <div class="arg-meta">${formatDate(a.created_at)}</div>
+            </div>`).join('')}
+      </div>
+    </div>
+
+    <div class="post-arg-panel">
+      <h3>Post an Argument</h3>
+      <div class="side-toggle">
+        <button class="side-btn active-for" id="side-for-btn" onclick="selectSide('for')">For</button>
+        <button class="side-btn" id="side-against-btn" onclick="selectSide('against')">Against</button>
+      </div>
+      <div class="form-group">
+        <label for="arg-content">Argument</label>
+        <textarea id="arg-content" placeholder="State your argument clearly and concisely…"></textarea>
+      </div>
+      <div class="form-actions">
+        <button class="btn btn-primary" id="post-arg-btn" onclick="submitArgument('${escAttr(debate.id)}')">Post Argument</button>
+      </div>
+    </div>
+  `;
+
+  // Reset side toggle state
+  argSide = 'for';
+}
+
+function selectSide(side) {
+  argSide = side;
+  const forBtn = document.getElementById('side-for-btn');
+  const againstBtn = document.getElementById('side-against-btn');
+  if (side === 'for') {
+    forBtn.className = 'side-btn active-for';
+    againstBtn.className = 'side-btn';
+  } else {
+    forBtn.className = 'side-btn';
+    againstBtn.className = 'side-btn active-against';
+  }
+}
+
+async function submitArgument(debateId) {
+  const content = document.getElementById('arg-content').value.trim();
+  if (!content) {
+    showError('Argument content cannot be empty.');
+    return;
+  }
+  const btn = document.getElementById('post-arg-btn');
+  btn.disabled = true;
+  btn.textContent = 'Posting…';
+  try {
+    await apiFetch(`/debates/${encodeURIComponent(debateId)}/arguments`, {
+      method: 'POST',
+      body: JSON.stringify({ side: argSide, content }),
+    });
+    // Reload detail to show the new argument
+    await loadDebateDetail(debateId);
+  } catch (err) {
+    showError('Failed to post argument: ' + err.message);
+    btn.disabled = false;
+    btn.textContent = 'Post Argument';
+  }
+}
+
+// ── XSS helpers ────────────────────────────────────────────────────
+
+function escHtml(str) {
+  return String(str)
+    .replace(/&/g, '&amp;')
+    .replace(/</g, '&lt;')
+    .replace(/>/g, '&gt;')
+    .replace(/"/g, '&quot;')
+    .replace(/'/g, '&#39;');
+}
+
+function escAttr(str) {
+  return String(str).replace(/'/g, '&#39;').replace(/"/g, '&quot;');
+}
+
+// ── Boot ───────────────────────────────────────────────────────────
+loadDebates();
+</script>
+</body>
+</html>

